from django.db.models import Q

def history(conversation_id, before=None, limit=50):
    """before = (created_at, id) of the oldest message the client already has."""
    qs = Message.objects.filter(conversation_id=conversation_id)
    if before:
        ts, last_id = before
        qs = qs.filter(Q(created_at__lt=ts) | Q(created_at=ts, id__lt=last_id))
    return list(qs.order_by('-created_at', '-id')[:limit])

