def two_sum_slow(nums, target):
    # try every pair: O(n^2) time, O(1) extra space
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return i, j
    return None

def two_sum_fast(nums, target):
    # one pass with a dict: O(n) time, O(n) extra space
    seen = {}                      # value -> index
    for i, x in enumerate(nums):
        if target - x in seen:     # O(1) average lookup
            return seen[target - x], i
        seen[x] = i
    return None

def binary_search(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1      # discard the left half and mid itself
        else:
            hi = mid - 1      # discard the right half and mid itself
    return -1                  # range became empty: not present

def pair_with_sum(a, target):      # a must be sorted
    l, r = 0, len(a) - 1
    while l < r:
        s = a[l] + a[r]
        if s == target:
            return a[l], a[r]
        if s < target:
            l += 1                  # need a bigger sum
        else:
            r -= 1                  # need a smaller sum
    return None

from collections import deque

def shortest_path(graph, start, goal):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == goal:
            return dist[node]
        for nb in graph[node]:
            if nb not in dist:       # the 'seen' check
                dist[nb] = dist[node] + 1
                queue.append(nb)
    return -1

import functools, time

def timed(fn):
    @functools.wraps(fn)            # keep fn.__name__ and its docstring
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return fn(*args, **kwargs)
        finally:
            print(f'{fn.__name__} took {time.perf_counter() - start:.3f}s')
    return wrapper

