def server_side(events):
    """A simplified server: SYN arrives -> reply SYN-ACK; the final ACK arrives -> connection established."""
    state = "LISTEN"
    for e in events:
        if state == "LISTEN" and e == "SYN":
            state = "SYN-ACK sent"
        elif state == "SYN-ACK sent" and e == "ACK":
            state = "ESTABLISHED"
    return state

assert server_side(["SYN", "ACK"]) == "ESTABLISHED"
assert server_side(["ACK"]) == "LISTEN"                  # an ACK with no SYN does nothing
assert server_side(["SYN"]) == "SYN-ACK sent"            # half-open until the last step

