def mean_shift(train_values, recent_values, threshold=3.0):
    """Crude drift check: how many training standard deviations has the mean moved?"""
    mu, sd = statistics.mean(train_values), statistics.stdev(train_values)
    shift = abs(statistics.mean(recent_values) - mu) / (sd or 1)
    return shift > threshold, round(shift, 2)

