import time

class TokenBucket:
    def __init__(self, capacity=10, refill_per_sec=2):
        self.capacity, self.rate = capacity, refill_per_sec
        self.tokens, self.t = capacity, time.monotonic()

    def allow(self):
        now = time.monotonic()
        self.tokens = min(self.capacity, self.tokens + (now - self.t) * self.rate)
        self.t = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False       # caller answers 429

