import random, time, requests

def call(url, key, attempts=3):
    for attempt in range(attempts):
        try:
            r = requests.post(url, json={'qty': 1}, timeout=(0.5, 2),     # connect, read
                              headers={'Idempotency-Key': key})
            if r.status_code < 500:
                return r
        except (requests.Timeout, requests.ConnectionError):
            pass
        # exponential backoff with full jitter
        time.sleep(random.uniform(0, min(2.0, 0.1 * 2 ** attempt)))
    raise RuntimeError('gave up')

import time

class Breaker:
    def __init__(self, threshold=5, reset_after=30):
        self.failures, self.opened_at = 0, None
        self.threshold, self.reset_after = threshold, reset_after

    def call(self, fn):
        if self.opened_at and time.time() - self.opened_at < self.reset_after:
            raise RuntimeError('open: failing fast')      # do not call at all
        try:
            result = fn()                                  # closed, or one half-open trial
        except Exception:
            self.failures += 1
            if self.failures >= self.threshold:
                self.opened_at = time.time()
            raise
        self.failures, self.opened_at = 0, None            # success closes it
        return result

