def min_speed(piles, hours):          # smallest k so that sum(ceil(p / k)) <= hours
    lo, hi = 1, max(piles)
    while lo < hi:
        mid = (lo + hi) // 2
        if sum(-(-p // mid) for p in piles) <= hours:
            hi = mid
        else:
            lo = mid + 1
    return lo

