from collections import deque

graph = {'A': ['B', 'C'], 'B': ['A', 'D'], 'C': ['A', 'E'], 'D': ['B', 'F'], 'E': ['C', 'F'], 'F': ['D', 'E']}

def bfs_dist(graph, start):
    dist, q = {start: 0}, deque([start])
    while q:
        node = q.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                q.append(nb)
    return dist

def dfs_order(graph, node, seen=None, out=None):
    seen = set() if seen is None else seen
    out = [] if out is None else out
    seen.add(node)
    out.append(node)
    for nb in graph[node]:
        if nb not in seen:
            dfs_order(graph, nb, seen, out)
    return out

