from dataclasses import dataclass
from enum import Enum
from typing import Optional
import itertools

class VehicleType(Enum):
    MOTORCYCLE = 1
    CAR = 2
    TRUCK = 3

class LotFull(Exception): ...
class UnknownTicket(Exception): ...

@dataclass
class Spot:
    id: int
    kind: VehicleType
    vehicle: Optional[str] = None

@dataclass
class Ticket:
    id: int
    spot: Spot
    plate: str
    entry_hour: float

class HourlyPricing:
    def __init__(self, rate):
        self.rate = rate
    def fee(self, hours):
        return round(max(1, -(-hours // 1)) * self.rate, 2)      # started hours, at least 1

class ParkingLot:
    def __init__(self, spots, pricing):
        self.spots, self.pricing = spots, pricing
        self.tickets, self._ids = {}, itertools.count(1)

    def park(self, plate, kind, now):
        spot = next((s for s in self.spots if s.kind == kind and s.vehicle is None), None)
        if spot is None:
            raise LotFull(kind)
        spot.vehicle = plate
        ticket = Ticket(next(self._ids), spot, plate, now)
        self.tickets[ticket.id] = ticket
        return ticket

    def unpark(self, ticket_id, now):
        ticket = self.tickets.pop(ticket_id, None)
        if ticket is None:
            raise UnknownTicket(ticket_id)
        ticket.spot.vehicle = None
        return self.pricing.fee(now - ticket.entry_hour)

lot = ParkingLot([Spot(1, VehicleType.CAR), Spot(2, VehicleType.MOTORCYCLE)], HourlyPricing(rate=3))
t = lot.park('KA01', VehicleType.CAR, now=9.0)
try:
    lot.park('KA02', VehicleType.CAR, now=9.5)           # the only car spot is taken
except LotFull:
    pass
else:
    raise AssertionError('should be full')
assert lot.unpark(t.id, now=11.5) == 9                  # 2.5 hours -> 3 started hours x 3
try:
    lot.unpark(t.id, now=12)                             # a used ticket is not accepted again
except UnknownTicket:
    pass
else:
    raise AssertionError('ticket reuse must fail')
assert lot.park('KA03', VehicleType.CAR, now=12).spot.id == 1   # the spot is free again

import threading

class SafeParkingLot(ParkingLot):
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
        self._lock = threading.Lock()
    def park(self, plate, kind, now):
        with self._lock:                                  # find-and-mark is one step
            return super().park(plate, kind, now)

