class Idle:
    def insert(self, m): m.money += 1; return HasMoney()
    def select(self, m): return self                    # ignored: no money yet
    def refund(self, m): return self

class HasMoney:
    def insert(self, m): m.money += 1; return self
    def select(self, m):
        if m.stock == 0:
            raise RuntimeError('out of stock')
        m.stock -= 1; m.money = 0
        m.dispensed += 1
        return Dispensing()
    def refund(self, m): m.money = 0; return Idle()

class Dispensing:
    def insert(self, m): return self                    # busy: ignore
    def select(self, m): return self
    def refund(self, m): return self

