    def __init__(self, stock):
        self.state, self.money, self.stock, self.dispensed = Idle(), 0, stock, 0
    def insert(self): self.state = self.state.insert(self)
    def select(self): self.state = self.state.select(self)
    def refund(self): self.state = self.state.refund(self)
    def done(self):
        if isinstance(self.state, Dispensing):
