from enum import Enum

class Dir(Enum):
    UP = 1
    DOWN = -1
    IDLE = 0

class Elevator:
    def __init__(self, eid, floor=0):
        self.id, self.floor, self.dir, self.stops = eid, floor, Dir.IDLE, set()

    def add_stop(self, floor):
        if floor == self.floor:
            return
        self.stops.add(floor)
        if self.dir == Dir.IDLE:
            self.dir = Dir.UP if floor > self.floor else Dir.DOWN

    def step(self):
        """Move one floor. Return the floor if the car stopped there, else None."""
        if not self.stops:
            self.dir = Dir.IDLE
            return None
        ahead = [f for f in self.stops if (f - self.floor) * self.dir.value > 0]
        if not ahead:                                   # nothing left this way: turn round
            self.dir = Dir.DOWN if self.dir == Dir.UP else Dir.UP
        self.floor += self.dir.value
        if self.floor in self.stops:
            self.stops.remove(self.floor)
            if not self.stops:
                self.dir = Dir.IDLE
            return self.floor
        return None

def run(elevator):
    visits = []
    while elevator.stops:
        stopped = elevator.step()
        if stopped is not None:
            visits.append(stopped)
    return visits

e = Elevator(1, floor=3)
for f in (5, 2, 7):
    e.add_stop(f)
assert run(e) == [5, 7, 2]       # keeps going up first, then turns round
assert e.dir == Dir.IDLE

