class State:
    """Each state decides what a button press means. The machine just forwards the call."""
    def insert(self, m, cents): raise NotImplementedError
    def select(self, m, slot): raise NotImplementedError
    def refund(self, m): raise NotImplementedError

class Idle(State):
    def insert(self, m, cents):
        m.credit += cents
        m.state = HasMoney()
        return "credit"
    def select(self, m, slot):
        return "insert money first"
    def refund(self, m):
        return "nothing to refund"

class HasMoney(State):
    def insert(self, m, cents):
        m.credit += cents
        return "credit"
    def select(self, m, slot):
        item = m.stock.get(slot)
        if item is None or item["qty"] == 0:
            return "sold out"
        if m.credit < item["price"]:
            return "need more money"
        m.credit -= item["price"]
        item["qty"] -= 1
        m.dispensed.append(slot)
        m.state = Idle() if m.credit == 0 else HasMoney()
        return "dispensed"
    def refund(self, m):
        m.returned += m.credit
        m.credit = 0
        m.state = Idle()
        return "refunded"

