        self.credit, self.returned, self.dispensed = 0, 0, []
        self.state = Idle()
    def insert(self, cents): return self.state.insert(self, cents)
    def select(self, slot): return self.state.select(self, slot)
    def refund(self): return self.state.refund(self)

