def make_change(amount, coins=(100, 50, 25, 10, 5, 1)):
    """Greedy change. It is correct for this coin system; say so, because it is not for every system."""
    result = {}
    for coin in coins:
        n, amount = divmod(amount, coin)
        if n:
            result[coin] = n
    assert amount == 0
    return result

