def split_equal(total, users):
    """Whole cents only. The first (total % n) people pay one cent more, so the parts add up exactly."""
    base, extra = divmod(total, len(users))
    return {u: base + (1 if i < extra else 0) for i, u in enumerate(users)}

def split_exact(total, amounts):
    assert sum(amounts.values()) == total, "parts must add up to the total"
    return dict(amounts)

def split_percent(total, percents):
    assert sum(percents.values()) == 100
    users = list(percents)
    parts = {u: total * percents[u] // 100 for u in users}
    for u in users[: total - sum(parts.values())]:          # hand out the leftover cents
        parts[u] += 1
    return parts

