function promiseAll(items) {
  return new Promise((resolve, reject) => {
    const arr = Array.from(items);
    if (arr.length === 0) return resolve([]);
    const results = new Array(arr.length);
    let remaining = arr.length;
    arr.forEach((item, i) => {
      Promise.resolve(item).then((value) => {
        results[i] = value;                          // keep input order
        if (--remaining === 0) resolve(results);
      }, reject);                                   // first rejection wins
    });
  });
}

async function retry(fn, times, delayMs = 10) {
  let lastError;
  for (let i = 0; i < times; i++) {
    try { return await fn(i); }
    catch (e) { lastError = e; await sleep(delayMs * 2 ** i); }
  }
  throw lastError;
}

(async () => {
  const slow = sleep(30).then(() => 'slow');
  const fast = sleep(5).then(() => 'fast');
  assert.deepStrictEqual(await promiseAll([slow, fast, 7]), ['slow', 'fast', 7]);   // input order, plain values kept
  assert.deepStrictEqual(await promiseAll([]), []);
  await assert.rejects(promiseAll([sleep(20), Promise.reject(new Error('boom'))]), /boom/);

  const result = await retry(async (attempt) => {
    if (attempt < 2) throw new Error('flaky');
    return 'ok';
  }, 5);
  assert.strictEqual(result, 'ok');
  await assert.rejects(retry(async () => { throw new Error('always'); }, 2), /always/);
})();

