function createSWR(fetcher, staleMs, now = () => Date.now()) {
  const cache = new Map();
  return async function get(key, onUpdate) {
    const hit = cache.get(key);
    const fresh = hit && now() - hit.at < staleMs;
    if (hit) onUpdate(hit.value);                  // show cached data immediately
    if (!fresh) {
      const value = await fetcher(key);            // refetch when stale or missing
      cache.set(key, { value, at: now() });
      onUpdate(value);
    }
  };
}

