function page(items, after, size) {               // cursor pagination over ordered ids
  const start = after == null ? 0 : items.findIndex((x) => x.id === after) + 1;
  const slice = items.slice(start, start + size);
  return { items: slice, next: slice.length === size ? slice[slice.length - 1].id : null };
}

