import threading

def run(interleaving):
    """Each 'thread' does: load counter, add one, store. The interleaving says who takes the next step."""
    counter = [50]
    local = {}
    pc = {0: 0, 1: 0}
    for t in interleaving:
        if pc[t] == 0:
            local[t] = counter[0]                # load
        elif pc[t] == 1:
            local[t] += 1                        # add
        else:
            counter[0] = local[t]                # store
        pc[t] += 1
    return counter[0]

