import random

class Replica:
    def __init__(self):
        self.data = {}                         # key -> (version, value)

class Cluster:
    def __init__(self, n=3, w=2, r=2):
        self.replicas = [Replica() for _ in range(n)]
        self.n, self.w, self.r, self.version = n, w, r, 0

    def put(self, key, value, reachable=None):
        self.version += 1
        targets = list(range(self.n)) if reachable is None else reachable
        acks = 0
        for i in targets:
            self.replicas[i].data[key] = (self.version, value)
            acks += 1
        if acks < self.w:
            raise RuntimeError('not enough replicas acknowledged')

    def get(self, key, ask):
        answers = [self.replicas[i].data.get(key, (0, None)) for i in ask[:self.r]]
        return max(answers)[1]                 # newest version among those asked

c = Cluster(n=3, w=2, r=2)
