class Origin:
    def __init__(self):
        self.requests = 0
    def fetch(self, path):
        self.requests += 1
        return f'content of {path}'

class Edge:
    def __init__(self, origin, ttl):
        self.origin, self.ttl, self.cache = origin, ttl, {}
        self.hits = self.misses = 0
    def get(self, path, now):
        entry = self.cache.get(path)
        if entry and now - entry[1] < self.ttl:
            self.hits += 1
            return entry[0]
        self.misses += 1
        body = self.origin.fetch(path)               # a pull CDN fetches on a miss
        self.cache[path] = (body, now)
        return body

origin = Origin()
edge = Edge(origin, ttl=60)
for t in range(0, 120, 2):                           # one request every 2 s for 2 minutes
    edge.get('/logo.png', now=t)
assert edge.misses == 2 and edge.hits == 58          # one miss per TTL window
assert origin.requests == 2                          # the origin saw 2 of 60 requests
assert round(edge.hits / (edge.hits + edge.misses), 3) == 0.967

import itertools

class Registry:
    def __init__(self):
        self.instances = {}                      # service -> list of (address, healthy)
    def register(self, service, address):
        self.instances.setdefault(service, []).append([address, True])
    def mark_down(self, service, address):
        for inst in self.instances[service]:
            if inst[0] == address:
                inst[1] = False
    def pick(self, service, counter=itertools.count()):
        healthy = [a for a, ok in self.instances[service] if ok]
        if not healthy:
            raise RuntimeError('no healthy instance of ' + service)
        return healthy[next(counter) % len(healthy)]

reg = Registry()
reg.register('orders', '10.0.0.1'); reg.register('orders', '10.0.0.2')
assert {reg.pick('orders'), reg.pick('orders')} == {'10.0.0.1', '10.0.0.2'}
reg.mark_down('orders', '10.0.0.1')
assert all(reg.pick('orders') == '10.0.0.2' for _ in range(5))      # callers stop using the dead instance

def client_ip(headers, peer, trusted_proxies):
    """Take the real client address from X-Forwarded-For, but only if the direct peer is a proxy we run."""
    if peer not in trusted_proxies:
        return peer                                   # a stranger could send any header: ignore it
    chain = [p.strip() for p in headers.get("X-Forwarded-For", "").split(",") if p.strip()]
    return chain[0] if chain else peer

trusted = {"10.0.0.5"}
assert client_ip({"X-Forwarded-For": "203.0.113.9"}, "10.0.0.5", trusted) == "203.0.113.9"
assert client_ip({"X-Forwarded-For": "6.6.6.6"}, "198.51.100.7", trusted) == "198.51.100.7"   # forged header ignored
assert client_ip({}, "10.0.0.5", trusted) == "10.0.0.5"

import itertools

class Router:
    """Writes go to the primary. Reads go to a replica, except right after the same user wrote (read-your-writes)."""
    def __init__(self, replicas, clock, sticky_seconds=5):
        self.replicas = itertools.cycle(replicas)
        self.clock, self.sticky = clock, sticky_seconds
        self.last_write = {}                       # user -> time of their last write

    def for_write(self, user):
        self.last_write[user] = self.clock()
        return "primary"

    def for_read(self, user):
        wrote = self.last_write.get(user)
        if wrote is not None and self.clock() - wrote < self.sticky:
            return "primary"                       # the replica may not have this user's write yet
        return next(self.replicas)

now = [100]
r = Router(["replica1", "replica2"], clock=lambda: now[0])
assert r.for_read("ann") == "replica1"             # no recent write: any replica
assert r.for_write("ann") == "primary"
assert r.for_read("ann") == "primary"              # just wrote: read from the primary
assert r.for_read("bob") == "replica2"             # bob never wrote: balanced over replicas
now[0] = 106                                       # more than 5 seconds later
assert r.for_read("ann") in {"replica1", "replica2"}

def parse_sse(text):
    """Turn a text/event-stream body into events. Messages end with a blank line; lines starting ':' are comments."""
    events, current = [], {"data": []}
    for line in text.split("\n"):
        if line == "":                                    # a blank line ends one message
            if current["data"]:
                events.append({"event": current.get("event", "message"), "id": current.get("id"), "data": "\n".join(current["data"])})
            current = {"data": []}
        elif line.startswith(":"):
            continue                                      # comment: often used as a keep-alive
        else:
            field, _, value = line.partition(":")
            value = value[1:] if value.startswith(" ") else value
            if field == "data":
                current["data"].append(value)
            elif field in ("event", "id"):
                current[field] = value
    return events

body = ": keep-alive\n\nid: 7\nevent: price\ndata: 101.5\n\ndata: line one\ndata: line two\n\n"
evs = parse_sse(body)
assert evs[0] == {"event": "price", "id": "7", "data": "101.5"}
assert evs[1] == {"event": "message", "id": None, "data": "line one\nline two"}    # two data lines are joined with a newline
assert len(evs) == 2

