_seen = {}

def handle_payment(idem_key, amount, store=_seen):
    """The same Idempotency-Key returns the same result, so a retry never charges twice."""
    if idem_key in store:
        return store[idem_key]
    result = {"status": "charged", "amount": amount, "id": f"pay_{len(store) + 1}"}
    store[idem_key] = result
    return result

a = handle_payment("key-1", 500)
b = handle_payment("key-1", 500)                  # the client retried after a timeout
assert a == b and len(_seen) == 1                 # one charge
