class Storage:
    """A resource that checks fencing tokens: it accepts a write only if the token is not older than one it has seen."""
    def __init__(self):
        self.value, self.highest = None, 0

    def write(self, value, token):
        if token < self.highest:
            return False                       # a stale lock holder is rejected
        self.highest, self.value = token, value
        return True

class LockService:
    """Every grant gets a larger number, the fencing token."""
    def __init__(self):
        self.token = 0
    def acquire(self):
        self.token += 1
        return self.token

locks, disk = LockService(), Storage()
token_a = locks.acquire()                      # client A gets 1, then pauses (a long GC pause, say)
token_b = locks.acquire()                      # A's lease expired, so B gets 2
assert disk.write("from B", token_b) is True
assert disk.write("from A (late)", token_a) is False     # A wakes up and writes, but token 1 is older than 2
assert disk.value == "from B"

