from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode

def normalize(url):
    p = urlsplit(url)
    query = urlencode(sorted(parse_qsl(p.query)))
    return urlunsplit((p.scheme, p.netloc.lower(), p.path or '/', query, ''))   # drop the fragment, sort params

assert normalize('HTTP://Example.com/a?b=2&a=1#top') == 'http://example.com/a?a=1&b=2'

class Frontier:
    """One queue per host and a minimum delay between hits to the same host."""
    def __init__(self, delay=1.0):
        self.delay, self.queues, self.seen, self.next_ok = delay, {}, set(), {}
    def add(self, url):
        url = normalize(url)
        if url in self.seen:
            return False
        self.seen.add(url)
        self.queues.setdefault(urlsplit(url).netloc, []).append(url)
        return True
    def next(self, now):
        for host, q in self.queues.items():
            if q and self.next_ok.get(host, 0) <= now:
                self.next_ok[host] = now + self.delay
                return q.pop(0)
        return None

f = Frontier(delay=1.0)
assert f.add('http://a.com/1') and f.add('http://a.com/2') and f.add('http://b.com/1')
assert not f.add('HTTP://A.com/1#frag')                  # duplicate after normalisation
first, second = f.next(0), f.next(0)
assert {urlsplit(first).netloc, urlsplit(second).netloc} == {'a.com', 'b.com'}   # rotates across hosts
assert f.next(0.5) is None                              # both hosts are cooling down
assert f.next(1.0) == 'http://a.com/2'

def allowed(rules, path):
    """RFC 9309: the most specific (longest) matching rule wins."""
    best, verdict = -1, True
    for kind, prefix in rules:
        if path.startswith(prefix) and len(prefix) > best:
            best, verdict = len(prefix), kind == 'allow'
    return verdict

rules = [('disallow', '/private/'), ('allow', '/private/public/')]
assert allowed(rules, '/index.html')
assert not allowed(rules, '/private/x')
assert allowed(rules, '/private/public/page')

import bisect, hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16)

class Store:
    def __init__(self, nodes, n=3, w=2, r=2, vnodes=8):
        self.n, self.w, self.r = n, w, r
        self.ring = sorted((h(f'{node}#{v}'), node) for node in nodes for v in range(vnodes))
        self.data = {node: {} for node in nodes}
        self.down, self.hints = set(), []
        self.clock = 0

    def owners(self, key):
        i = bisect.bisect(self.ring, (h(key),)) % len(self.ring)
        out = []
        while len(out) < len(self.data):                       # walk the ring, collect distinct nodes
            node = self.ring[i % len(self.ring)][1]
            if node not in out:
                out.append(node)
            i += 1
        return out

    def put(self, key, value):
        self.clock += 1
        owners = self.owners(key)
        preferred, spare = owners[:self.n], owners[self.n:]
        acks = 0
        for node in preferred:
            if node in self.down:                               # hinted handoff: a spare node holds it for the owner
                if spare:
                    self.hints.append((spare[0], node, key, (self.clock, value)))
                    self.data[spare[0]][key] = (self.clock, value)
                    acks += 1
            else:
                self.data[node][key] = (self.clock, value)
                acks += 1
        if acks < self.w:
            raise RuntimeError('write quorum not met')

    def get(self, key):
        answers = [self.data[n][key] for n in self.owners(key)[:self.n] if n not in self.down and key in self.data[n]]
        if len(answers) < self.r:
            raise RuntimeError('read quorum not met')
        return max(answers)[1]

    def recover(self, node):
        self.down.discard(node)
        for spare, owner, key, ver in list(self.hints):
            if owner == node:
                self.data[owner][key] = ver
                self.hints.remove((spare, owner, key, ver))

s = Store(['a', 'b', 'c', 'd'], n=3, w=2, r=2)
s.put('x', 1)
assert s.get('x') == 1
victim = s.owners('x')[0]
s.down.add(victim)
s.put('x', 2)                                                  # a replica is down: still succeeds (W=2 met)
assert s.get('x') == 2
s.recover(victim)
assert s.data[victim]['x'][1] == 2                             # the hint was handed back

from collections import OrderedDict

class LRU:
    def __init__(self, size):
        self.size, self.d = size, OrderedDict()
    def get(self, k):
        if k not in self.d:
            return None
        self.d.move_to_end(k)
        return self.d[k]
    def set(self, k, v):
        self.d[k] = v
        self.d.move_to_end(k)
        if len(self.d) > self.size:
            self.d.popitem(last=False)

def shard(query, machines):
    return h(query) % machines                                # hash(query) picks the machine

c = LRU(2)
c.set('a', 1); c.set('b', 2); c.get('a'); c.set('c', 3)
assert c.get('b') is None and c.get('a') == 1
assert 0 <= shard('pizza near me', 4) < 4

import random
from collections import deque

class Provider:
    def __init__(self, fail_times=0, permanent=False):
        self.fail_times, self.permanent, self.sent = fail_times, permanent, []
    def send(self, n):
        if self.permanent:
            raise ValueError('invalid token')               # a permanent failure
        if self.fail_times:
            self.fail_times -= 1
            raise TimeoutError('provider timeout')           # a transient failure
        self.sent.append(n['id'])

def backoff(attempt, base=1.0, rng=random.Random(1)):
    return base * 2 ** attempt + rng.uniform(0, 0.1)         # exponential backoff with jitter

class Worker:
    def __init__(self, provider, max_attempts=4):
        self.provider, self.max_attempts = provider, max_attempts
        self.seen, self.dead, self.delays = set(), [], []
    def handle(self, n):
        if n['id'] in self.seen:
            return 'duplicate'
        for attempt in range(self.max_attempts):
            try:
                self.provider.send(n)
                self.seen.add(n['id'])
                return 'sent'
            except TimeoutError:
                self.delays.append(backoff(attempt))
            except ValueError:
                break                                       # do not retry permanent errors
        self.dead.append(n)
        return 'dead-lettered'

w = Worker(Provider(fail_times=2))
assert w.handle({'id': 'n1'}) == 'sent'
assert len(w.delays) == 2 and w.delays[1] > w.delays[0]      # waits grow
assert w.handle({'id': 'n1'}) == 'duplicate'                  # a redelivered message is not sent twice
assert w.provider.sent == ['n1']

bad = Worker(Provider(permanent=True))
assert bad.handle({'id': 'n2'}) == 'dead-lettered' and bad.delays == []   # no retries for a permanent failure
assert [n['id'] for n in bad.dead] == ['n2']

import heapq, itertools

class Limiter:
    def __init__(self, per_window, window):
        self.per_window, self.window, self.hits = per_window, window, {}
    def allow(self, user, now):
        recent = [t for t in self.hits.get(user, []) if now - t < self.window]
        if len(recent) >= self.per_window:
            self.hits[user] = recent
            return False
        self.hits[user] = recent + [now]
        return True

lim = Limiter(per_window=3, window=60)
assert [lim.allow('u', t) for t in (0, 1, 2, 3, 61)] == [True, True, True, False, True]

class PriorityQueue:
    def __init__(self):
        self.h, self.c = [], itertools.count()
    def put(self, priority, item):
        heapq.heappush(self.h, (priority, next(self.c), item))     # lower number = more urgent
    def get(self):
        return heapq.heappop(self.h)[2]

pq = PriorityQueue()
pq.put(5, 'promo'); pq.put(1, 'security code'); pq.put(5, 'promo 2')
assert [pq.get() for _ in range(3)] == ['security code', 'promo', 'promo 2']

import heapq

class Node:
    def __init__(self):
        self.children, self.top = {}, []

def build(counts, k=3):
    root = Node()
    for query, count in counts.items():
        node = root
        for ch in query:
            node = node.children.setdefault(ch, Node())
            node.top.append((count, query))
    def trim(n):
        n.top = [q for _c, q in heapq.nlargest(k, n.top)]
        for c in n.children.values():
            trim(c)
    trim(root)
    return root

def suggest(root, prefix):
    node = root
    for ch in prefix:
        node = node.children.get(ch)
        if node is None:
            return []
    return node.top

counts = {'harry potter': 90, 'hair salon': 40, 'hardware store': 60, 'happy birthday': 75, 'hat': 5, 'dog': 50}
root = build(counts, k=3)
assert suggest(root, 'ha') == ['harry potter', 'happy birthday', 'hardware store']   # top 3 by count
assert suggest(root, 'hai') == ['hair salon']
assert suggest(root, 'zzz') == []
assert suggest(root, 'd') == ['dog']

def merge(stable, trending, k=3):
    """stable and trending are [(query, score)]. Trending scores are boosted so a surge can enter the top k."""
    scores = {}
    for q, s in stable:
        scores[q] = scores.get(q, 0) + s
    for q, s in trending:
        scores[q] = scores.get(q, 0) + 5 * s                   # an illustrative boost for recent activity
    return [q for q, _ in sorted(scores.items(), key=lambda kv: -kv[1])[:k]]

stable = [('weather', 100), ('wedding dresses', 80), ('web mail', 60)]
trending = [('world cup final', 30)]
assert merge(stable, []) == ['weather', 'wedding dresses', 'web mail']
assert merge(stable, trending) == ['world cup final', 'weather', 'wedding dresses']   # a surge displaces a stable item

import hashlib

BLOCK = 4                                           # 4 bytes here; Dropbox uses 4 MB

def blocklist(data: bytes):
    blocks = [data[i:i + BLOCK] for i in range(0, len(data), BLOCK)]
    return [hashlib.sha256(b).hexdigest() for b in blocks], blocks

class Server:
    def __init__(self):
        self.blocks, self.files = {}, {}                # hash -> bytes, name -> blocklist
    def commit(self, name, hashes):
        missing = [h for h in dict.fromkeys(hashes) if h not in self.blocks]
        if missing:
            return ('need blocks', missing)
        self.files[name] = hashes                        # the metadata journal entry
        return ('ok', [])
    def upload(self, h, data):
        assert hashlib.sha256(data).hexdigest() == h      # verify by hash
        self.blocks[h] = data
    def download(self, name):
        return b''.join(self.blocks[h] for h in self.files[name])

def sync(server, name, data):
    hashes, blocks = blocklist(data)
    by_hash = dict(zip(hashes, blocks))
    status, missing = server.commit(name, hashes)
    for h in missing:
        server.upload(h, by_hash[h])
    if missing:
        server.commit(name, hashes)
    return len(missing)

s = Server()
assert sync(s, 'doc.txt', b'aaaabbbbccccdddd') == 4        # a new file: all 4 blocks upload
assert s.download('doc.txt') == b'aaaabbbbccccdddd'
assert sync(s, 'doc.txt', b'aaaabbbbXXXXdddd') == 1        # one block edited: only one block uploads
assert sync(s, 'copy.txt', b'aaaabbbbccccdddd') == 0        # identical content already stored: nothing to upload
assert s.download('doc.txt') == b'aaaabbbbXXXXdddd'

def relation(a, b):
    """a and b are lists of blocklist ids, oldest first. Returns how they relate."""
    if a == b:
        return 'same'
    if b[:len(a)] == a:
        return 'b is newer'
    if a[:len(b)] == b:
        return 'a is newer'
    return 'conflict'                                   # the histories diverged

base = ['v1']
assert relation(base, ['v1', 'v2']) == 'b is newer'
assert relation(['v1', 'v2a'], ['v1', 'v2b']) == 'conflict'   # two devices edited offline: keep both

LADDER = [('240p', 300_000), ('480p', 1_000_000), ('720p', 3_000_000), ('1080p', 6_000_000)]    # illustrative bitrates

def segments(duration_s, seg_s=10):
    return -(-duration_s // seg_s)                       # ceiling division

def storage_bytes(duration_s, ladder=LADDER):
    return sum(bps * duration_s // 8 for _name, bps in ladder)

def hls_playlist(prefix, duration_s, seg_s=10):
    lines = ['#EXTM3U', '#EXT-X-VERSION:3', f'#EXT-X-TARGETDURATION:{seg_s}']
    for i in range(segments(duration_s, seg_s)):
        length = min(seg_s, duration_s - i * seg_s)
        lines += [f'#EXTINF:{length:.1f},', f'{prefix}/segment{i + 1}.ts']
    return '\n'.join(lines + ['#EXT-X-ENDLIST'])

assert segments(95) == 10 and segments(100) == 10
assert storage_bytes(60) == (300_000 + 1_000_000 + 3_000_000 + 6_000_000) * 60 // 8    # all qualities are stored
playlist = hls_playlist('http://media.example.com/v1/720p', 25)
assert playlist.count('#EXTINF') == 3 and '#EXTINF:5.0,' in playlist and playlist.endswith('#EXT-X-ENDLIST')

def choose(ladder_bps, throughput_bps, buffer_s, current):
    """ladder_bps is sorted ascending. Never pick a bitrate above 80% of measured throughput;
    step down quickly when the buffer is low, up slowly when it is healthy."""
    affordable = [i for i, b in enumerate(ladder_bps) if b <= 0.8 * throughput_bps]
    best = affordable[-1] if affordable else 0
    if buffer_s < 5:
        return min(current, best, max(current - 1, 0))      # drop at once
    if buffer_s > 15 and best > current:
        return current + 1                                   # climb one step at a time
    return min(current, best)

ladder = [300_000, 1_000_000, 3_000_000, 6_000_000]
assert choose(ladder, 2_000_000, 20, 0) == 1                 # healthy buffer: step up one
assert choose(ladder, 8_000_000, 20, 2) == 3
assert choose(ladder, 500_000, 3, 3) == 0                    # throughput collapsed, buffer low: drop

import math

CELL = 0.01                                           # degrees per cell side (illustrative resolution)

def cell(lat, lng):
    return (math.floor(lat / CELL), math.floor(lng / CELL))

def ring(c, k=1):
    return [(c[0] + i, c[1] + j) for i in range(-k, k + 1) for j in range(-k, k + 1)]

def distance_km(a, b):
    la1, lo1, la2, lo2 = map(math.radians, (*a, *b))
    d = math.sin((la2 - la1) / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2
    return 6371 * 2 * math.asin(math.sqrt(d))          # haversine

class Index:
    def __init__(self):
        self.cells, self.where, self.seen = {}, {}, {}
    def update(self, driver, lat, lng, now):
        new = cell(lat, lng)
        old = self.where.get(driver)
        if old != new:                                    # moved to another cell
            if old is not None:
                self.cells[old].discard(driver)
            self.cells.setdefault(new, set()).add(driver)
            self.where[driver] = new
        self.seen[driver] = (lat, lng, now)
    def nearby(self, lat, lng, km, now, ttl=30):
        out = []
        for c in ring(cell(lat, lng)):
            for d in self.cells.get(c, ()):
                dlat, dlng, t = self.seen[d]
                if now - t <= ttl:                         # ignore drivers that stopped pinging
                    dist = distance_km((lat, lng), (dlat, dlng))
                    if dist <= km:
                        out.append((round(dist, 2), d))
        return sorted(out)

idx = Index()
idx.update('d1', 12.9716, 77.5946, now=0)
idx.update('d2', 12.9750, 77.5990, now=0)              # about 0.6 km away
idx.update('d3', 13.2000, 77.9000, now=0)              # far away: other cells
assert [d for _x, d in idx.nearby(12.9716, 77.5946, 2, now=5)] == ['d1', 'd2']
idx.update('d2', 13.2001, 77.9001, now=6)              # d2 moves next to d3
assert [d for _x, d in idx.nearby(12.9716, 77.5946, 2, now=7)] == ['d1']
