class Provider:
    def __init__(self):
        self.charges, self.fail_next_response = {}, False
    def charge(self, key, amount):
        if key not in self.charges:                           # the provider also dedupes by key
            self.charges[key] = amount
        if self.fail_next_response:
            self.fail_next_response = False
            raise TimeoutError('response lost')             # the charge happened but we did not hear back
        return 'ok'

class Payments:
    def __init__(self, provider):
        self.provider, self.keys, self.ledger = provider, {}, []
    def pay(self, key, order, amount):
        if key in self.keys:
            state = self.keys[key]
            if state['status'] == 'succeeded':
                return state['result']                         # replay the stored result: no second charge
            if state['status'] == 'processing':
                pass                                           # recovering an unfinished payment with the same key
        else:
            self.keys[key] = {'status': 'processing', 'result': None}
        try:
            self.provider.charge(key, amount)
        except TimeoutError:
            return 'unknown: retry with the same key'
        self.keys[key] = {'status': 'succeeded', 'result': 'paid'}
        self.ledger += [('customer', -amount, order), ('merchant', amount, order)]   # debit and equal credit
        return 'paid'

prov = Provider()
pay = Payments(prov)
prov.fail_next_response = True
assert pay.pay('k1', 'order17', 50) == 'unknown: retry with the same key'
assert pay.pay('k1', 'order17', 50) == 'paid'                  # the retry reuses the key
assert pay.pay('k1', 'order17', 50) == 'paid'                  # a further retry replays the result
assert prov.charges == {'k1': 50}                              # charged exactly once
assert sum(amount for _acct, amount, _o in pay.ledger) == 0    # the ledger always sums to zero
assert len(pay.ledger) == 2

ALLOWED = {('created', 'processing'), ('processing', 'succeeded'), ('processing', 'failed'), ('succeeded', 'refunded')}

class Payment:
    def __init__(self):
        self.state = 'created'
    def move(self, expected, new):
        """Like UPDATE ... WHERE state = expected: only one caller can win."""
        if self.state != expected or (expected, new) not in ALLOWED:
            return False
        self.state = new
        return True

p = Payment()
assert p.move('created', 'processing')
assert not p.move('created', 'processing')             # a second worker loses the race
assert not p.move('processing', 'refunded')            # not an allowed transition
assert p.move('processing', 'succeeded') and p.move('succeeded', 'refunded')

def reconcile(ledger_entries, provider_report):
    mine = {key: amount for key, amount in ledger_entries}
    theirs = dict(provider_report)
    return {
        'charged_not_recorded': sorted(k for k in theirs if k not in mine),
        'recorded_not_charged': sorted(k for k in mine if k not in theirs),
        'amount_mismatch': sorted(k for k in mine if k in theirs and mine[k] != theirs[k]),
    }

