def nearest(user_vec, k):
    return sorted(items, key=lambda i: -cosine(user_vec, items[i]))[:k]
assert nearest([0.9, 0.1, 0.0], 2) == ['cat video', 'dog video']        # content-based: close in the embedding space

likes = {'A': {'v1', 'v2'}, 'B': {'v1', 'v2', 'v7'}, 'C': {'v9'}}
def collaborative(user, k=1):
    seen, scores = likes[user], Counter()
    for other, theirs in likes.items():
        if other == user:
            continue
        overlap = len(seen & theirs) / len(seen | theirs)             # Jaccard similarity of tastes
        for item in theirs - seen:
            scores[item] += overlap
    return [i for i, _s in scores.most_common(k)]
assert collaborative('A') == ['v7']                                      # what similar user B liked and A has not seen

def rerank(scored, seen, max_per_topic=2, k=4):
    """scored is [(item, topic, score)], best first. Drop seen items and limit each topic, as a list-level rule."""
    out, per_topic = [], {}
    for item, topic, _score in sorted(scored, key=lambda t: -t[2]):
        if item in seen or per_topic.get(topic, 0) >= max_per_topic:
            continue
        per_topic[topic] = per_topic.get(topic, 0) + 1
        out.append(item)
        if len(out) == k:
            break
    return out

