function collapse(bottom, top) {                                            // adjacent vertical margins
  if (bottom >= 0 && top >= 0) return Math.max(bottom, top);              // two positive margins: the largest
  if (bottom < 0 && top < 0) return Math.min(bottom, top);                // two negative margins: furthest from zero
  return bottom + top;                                                     // one negative: subtracted
}
assert.strictEqual(collapse(50, 30), 50);
assert.strictEqual(collapse(50, -10), 40);
assert.strictEqual(collapse(-20, -5), -20);

function flexShares(total, grows) {                                         // flex: 1, flex: 1, flex: 2 share the free space
  const sum = grows.reduce((a, b) => a + b, 0);
  return grows.map((g) => (total * g) / sum);
}
assert.deepStrictEqual(flexShares(800, [1, 1, 2]), [200, 200, 400]);

function frTracks(container, gap, frs) {                                    // grid-template-columns: 2fr 1fr 1fr; gap
  const free = container - gap * (frs.length - 1);
  const sum = frs.reduce((a, b) => a + b, 0);
  return frs.map((f) => (free * f) / sum);
}
