assert not is_palindrome("race a car")

def dedupe_sorted_in_place(nums):
    """Return the length of the unique prefix; the slow pointer marks where the next new value goes."""
    if not nums:
        return 0
    slow = 0
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1
            nums[slow] = nums[fast]
    return slow + 1

data = [1, 1, 2, 2, 2, 3]
k = dedupe_sorted_in_place(data)
assert k == 3 and data[:k] == [1, 2, 3]

class Trie:
    END = "$"

    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node[self.END] = True

    def _walk(self, text):
        node = self.root
        for ch in text:
            if ch not in node:
                return None
            node = node[ch]
        return node

    def contains(self, word):
        node = self._walk(word)
        return node is not None and self.END in node

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

    def autocomplete(self, prefix, limit=5):
        node = self._walk(prefix)
        if node is None:
            return []
        out = []

        def dfs(n, path):
            if len(out) >= limit:
                return
            if self.END in n:
                out.append(prefix + "".join(path))
            for ch in sorted(k for k in n if k != self.END):
                path.append(ch)
                dfs(n[ch], path)
                path.pop()

        dfs(node, [])
        return out

