class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.groups = n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]   # path halving
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False                                   # already connected
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra                               # smaller tree under the larger
        self.size[ra] += self.size[rb]
        self.groups -= 1
        return True

uf = UnionFind(5)
assert uf.union(0, 1) and uf.union(2, 3) and uf.union(1, 3)
assert uf.find(0) == uf.find(3) and uf.find(4) != uf.find(0)
assert uf.groups == 2
assert uf.union(0, 3) is False

def count_components(n, edges):
    uf = UnionFind(n)
    for a, b in edges:
        uf.union(a, b)
    return uf.groups

assert count_components(5, [(0, 1), (1, 2), (3, 4)]) == 2

def first_redundant_edge(n, edges):
    """The edge that closes a cycle in an undirected graph."""
    uf = UnionFind(n)
    for a, b in edges:
        if not uf.union(a, b):
            return (a, b)
    return None

assert first_redundant_edge(4, [(0, 1), (1, 2), (2, 3), (3, 0)]) == (3, 0)
assert first_redundant_edge(3, [(0, 1), (1, 2)]) is None

import heapq

def max_non_overlapping(intervals):
    count, end = 0, float("-inf")
    for s, e in sorted(intervals, key=lambda x: x[1]):
        if s >= end:
            count += 1
            end = e
    return count

