assert max_non_overlapping(meetings) == 3
assert max_non_overlapping([]) == 0
assert max_non_overlapping([(1, 2), (2, 3), (3, 4)]) == 3          # touching is allowed

def min_removals_for_no_overlap(intervals):
    return len(intervals) - max_non_overlapping(intervals)

assert min_removals_for_no_overlap([(1, 2), (2, 3), (3, 4), (1, 3)]) == 1

def min_meeting_rooms(intervals):
    rooms = []                                     # min-heap of end times of rooms in use
    for s, e in sorted(intervals):
        if rooms and rooms[0] <= s:
            heapq.heapreplace(rooms, e)            # reuse the room that frees up first
        else:
            heapq.heappush(rooms, e)
    return len(rooms)

assert min_meeting_rooms([(0, 30), (5, 10), (15, 20)]) == 2
assert min_meeting_rooms([(7, 10), (2, 4)]) == 1

def can_jump(nums):
    far = 0
    for i, step in enumerate(nums):
        if i > far:
            return False
        far = max(far, i + step)
    return True

assert can_jump([2, 3, 1, 1, 4]) and not can_jump([3, 2, 1, 0, 4])

def coin_change_greedy(coins, amount):
    count = 0
    for c in sorted(coins, reverse=True):
        count += amount // c
        amount %= c
    return count if amount == 0 else -1

def coin_change_dp(coins, amount):
    INF = amount + 1
    best = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                best[a] = min(best[a], best[a - c] + 1)
    return best[amount] if best[amount] != INF else -1

assert coin_change_greedy([1, 5, 10, 25], 63) == 6              # works for standard coins
assert coin_change_greedy([1, 3, 4], 6) == 3                    # 4 + 1 + 1: greedy is not optimal here
assert coin_change_dp([1, 3, 4], 6) == 2                        # 3 + 3
assert coin_change_dp([2], 3) == -1

import math
import re
from collections import defaultdict, Counter

STOP = {"the", "a", "an", "are", "is", "of", "and"}

def analyze(text):
    tokens = re.findall(r"[a-z0-9]+", text.lower())
    out = []
    for t in tokens:
        if t in STOP:
            continue
        for suffix in ("ing", "s"):
            if t.endswith(suffix) and len(t) > len(suffix) + 2:
                t = t[: -len(suffix)]
                if suffix == "ing" and len(t) > 2 and t[-1] == t[-2]:
                    t = t[:-1]                       # running -> runn -> run
                break
        out.append(t)
    return out

class Index:
    def __init__(self):
        self.postings = defaultdict(dict)        # term -> {doc_id: term count}
        self.length = {}

    def add(self, doc_id, text):
        tokens = analyze(text)
        self.length[doc_id] = len(tokens)
        for term, n in Counter(tokens).items():
            self.postings[term][doc_id] = n

    def search(self, query, k=3):
        terms = analyze(query)
        if not terms or any(t not in self.postings for t in terms):
            return []
        ids = set(self.postings[terms[0]])
        for t in terms[1:]:
            ids &= set(self.postings[t])          # AND: intersect the postings
        n_docs = len(self.length)
        scores = {}
        for d in ids:
            s = 0.0
            for t in terms:
                tf = self.postings[t][d] / self.length[d]
                idf = math.log((1 + n_docs) / (1 + len(self.postings[t]))) + 1
                s += tf * idf
            scores[d] = s
        return sorted(scores, key=lambda d: (-scores[d], d))[:k]

ix = Index()
ix.add(1, "The fast red car")
ix.add(3, "A fast car, a fast car, a fast car and a slow train")
ix.add(4, "Cars are running on the road")
ix.add(9, "Running shoes")
assert analyze("The Fast Cars are Running!") == ["fast", "car", "run"]
assert set(ix.search("fast car")) == {1, 3}
assert ix.search("fast car")[0] == 3                     # the term appears more often in doc 3
assert ix.search("unicorn") == []
assert 4 in ix.search("car") and 9 not in ix.search("car")

def intersect(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return out

