assert network_delay_time([(1, 2, 1)], 2, 2) == -1

def cheapest_with_stops(n, flights, src, dst, k):
    """Bellman-Ford limited to k + 1 edges; each round reads the previous round's distances."""
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    for _ in range(k + 1):
        nxt = dist[:]
        for u, v, w in flights:
            if dist[u] + w < nxt[v]:
                nxt[v] = dist[u] + w
        dist = nxt
    return -1 if dist[dst] == INF else dist[dst]

flights = [(0, 1, 100), (1, 2, 100), (0, 2, 500)]
assert cheapest_with_stops(3, flights, 0, 2, 1) == 200
assert cheapest_with_stops(3, flights, 0, 2, 0) == 500
assert cheapest_with_stops(3, [(0, 1, 5)], 0, 2, 3) == -1

import heapq

def dijkstra_finalizing(graph, source):
    """Dijkstra that never reopens a finished node: correct only for non-negative weights."""
    dist, done, heap = {source: 0}, set(), [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if u in done:
            continue
        done.add(u)
        for v, w in graph.get(u, []):
            if v not in done and d + w < dist.get(v, float("inf")):
                dist[v] = d + w
                heapq.heappush(heap, (d + w, v))
    return dist

neg = {"S": [("B", 1), ("A", 2)], "A": [("B", -2)]}
assert dijkstra_finalizing(neg, "S")["B"] == 1       # wrong: the true cheapest cost is 2 + (-2) = 0

def bellman_ford(nodes, edges, source):
    dist = {v: float("inf") for v in nodes}
    dist[source] = 0
    for _ in range(len(nodes) - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist

assert bellman_ford("SAB", [("S", "B", 1), ("S", "A", 2), ("A", "B", -2)], "S")["B"] == 0

from bisect import bisect_left, bisect_right

def lower_bound(a, target):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def upper_bound(a, target):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo

