class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return (self.x, self.y) == (other.x, other.y)

assert Point(1, 2) == Point(1, 2)
assert Point.__hash__ is None                        # defining __eq__ alone removes __hash__
try:
    {Point(1, 2)}
    raise AssertionError("expected a TypeError")
except TypeError:
    pass

class HPoint(Point):
    def __hash__(self):
        return hash((self.x, self.y))

assert len({HPoint(1, 2), HPoint(1, 2)}) == 1

from dataclasses import dataclass, field, FrozenInstanceError

@dataclass
class Cart:
    owner: str
    items: list = field(default_factory=list)       # a plain [] default would raise ValueError

a, b = Cart("ana"), Cart("bo")
a.items.append("pen")
assert b.items == [] and a != b and repr(a) == "Cart(owner='ana', items=['pen'])"

@dataclass(frozen=True, order=True)
class Version:
    major: int
    minor: int = 0

assert Version(1, 2) < Version(1, 10) and len({Version(1), Version(1)}) == 1
try:
    Version(1).major = 2
    raise AssertionError("expected FrozenInstanceError")
except FrozenInstanceError:
    pass

