class Countdown:
    """An iterable that can be looped over more than once (the iterator is a separate object)."""
    def __init__(self, start):
        self.start = start
    def __iter__(self):
        n = self.start
        while n > 0:
            yield n
            n -= 1
    def __len__(self):
        return self.start
    def __bool__(self):
        return self.start > 0

c = Countdown(3)
assert list(c) == [3, 2, 1] and list(c) == [3, 2, 1] and len(c) == 3 and not Countdown(0)

class Timer:
    log = []
    def __enter__(self):
        Timer.log.append("start")
        return self
    def __exit__(self, exc_type, exc, tb):
        Timer.log.append("stop")
        return False                                  # do not swallow exceptions

try:
    with Timer():
        raise KeyError("boom")
except KeyError:
    pass
assert Timer.log == ["start", "stop"]                # cleanup ran even though an exception was raised

import bisect
import hashlib

def h(text):
    return int(hashlib.md5(text.encode()).hexdigest(), 16)

class Ring:
    def __init__(self, nodes, vnodes=100):
        self.vnodes = vnodes
        self.points = []                       # sorted list of (hash, node)
        for n in nodes:
            self.add(n)

    def add(self, node):
        for i in range(self.vnodes):
            bisect.insort(self.points, (h(f"{node}#{i}"), node))

    def remove(self, node):
        self.points = [p for p in self.points if p[1] != node]

    def owner(self, key):
        i = bisect.bisect(self.points, (h(key), ""))
        return self.points[i % len(self.points)][1]       # wrap around the ring

keys = [f"user:{i}" for i in range(20000)]
ring = Ring(["n1", "n2", "n3"])
before = {k: ring.owner(k) for k in keys}
ring.add("n4")
moved = sum(1 for k in keys if ring.owner(k) != before[k])
assert 0.15 < moved / len(keys) < 0.35                 # about 1/4 move, not 3/4
assert all(ring.owner(k) == "n4" for k in keys if ring.owner(k) != before[k])   # moved keys all go to the new node

# the naive modulo rule moves most keys
mod_before = {k: h(k) % 3 for k in keys}
mod_moved = sum(1 for k in keys if h(k) % 4 != mod_before[k])
assert mod_moved / len(keys) > 0.65

counts = {}
for k in keys:
    counts[ring.owner(k)] = counts.get(ring.owner(k), 0) + 1
assert min(counts.values()) > 0.15 * len(keys)          # virtual nodes keep the load fairly even

def evaluate_alert(points, threshold, for_seconds):
    """points: list of (timestamp, value). Fire when the value stays above the threshold for for_seconds."""
    started = None
    for t, v in points:
        if v > threshold:
            if started is None:
                started = t
            if t - started >= for_seconds:
                return t                              # firing since this time
        else:
            started = None                            # a dip resets the timer
    return None

errors = [(0, 0.01), (60, 0.09), (120, 0.08), (180, 0.07), (240, 0.09), (300, 0.08), (360, 0.09)]
assert evaluate_alert(errors, 0.05, 300) == 360       # above 5% from t=60 to t=360
blip = [(0, 0.01), (60, 0.09), (120, 0.01), (180, 0.09), (240, 0.01)]
assert evaluate_alert(blip, 0.05, 120) is None        # short spikes do not page anyone

def series_count(label_values):
    """Number of series for one metric: the product of the distinct values of each label."""
    total = 1
    for values in label_values.values():
        total *= len(values)
    return total

bounded = {"service": range(50), "status": range(5), "method": range(4)}
assert series_count(bounded) == 1000
with_user = dict(bounded, user_id=range(1_000_000))
assert series_count(with_user) == 1_000_000_000         # one label with unbounded values destroys the system
